parameters.jsCode:
const gerado = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const o = $('Detecta Urgentes').item.json;

let linkFinal = o.link_afiliado || o.link_original;
if (o.fonte === 'amazon' && !o.link_afiliado) {
  linkFinal = o.link_original.includes('?') 
    ? `${o.link_original}&tag=${$env.AMAZON_PARTNER_TAG}`
    : `${o.link_original}?tag=${$env.AMAZON_PARTNER_TAG}`;
}

const postFinal = `⚡ *URGENTE — RELÂMPAGO*\n\n${gerado}\n\n👉 ${linkFinal}\n\n_Corre antes de acabar_`;
return { json: { ...o, postFinal, linkFinal } };
